(3572155, 500762, 70, '<td valign="top">I''m eatin'' at your house. Nice lighting, hard with super reflective stuff. I think I''d prefer it if you didn''t cut off the top of the bottle.</td>', 'I''m eatin'' at your house. Nice lighting, hard with super reflective stuff. I think I''d prefer it if you didn''t cut off the top of the bottle.', '2007-04-23 01:31:30.000000', NULL, 1),
(3572156, 501409, 36371, '<td valign="top">The window light is over exposed, but overall a good photo. Nice, muted colors.</td>', 'The window light is over exposed, but overall a good photo. Nice, muted colors.', '2007-04-23 01:31:49.000000', NULL, 1),
(3572160, 501409, 6804, '<td valign="top">This is beautiful! What a great entry for this challenge.  I really like the flames showing through the oven door. It almost brings life to the old feeling of the room.  The glare from the window is showing the first light of morning and the coffee is waiting to be poured. I know how hard it is to shoot into the light from a dark room, but I''d love to see a little more detail in the shadows here.  High marks from me 9.</td>', 'This is beautiful! What a great entry for this challenge.  I really like the flames showing through the oven door. It almost brings life to the old feeling of the room.  The glare from the window is showing the first light of morning and the coffee is waiting to be poured. I know how hard it is to shoot into the light from a dark room, but I''d love to see a little more detail in the shadows here.  High marks from me 9.', '2007-04-23 01:33:01.000000', NULL, 1),
(3572166, 500805, 73124, '<td valign="top">Looks way too blurry to me.</td>', 'Looks way too blurry to me.', '2007-04-23 01:36:10.000000', NULL, 1),
