(3572185, 501438, 6804, '<td valign="top">Beautiful!  A great composition and awesome color tones.</td>', 'Beautiful!  A great composition and awesome color tones.', '2007-04-23 01:43:40.000000', NULL, 1),
(3572193, 501140, 76430, '<td valign="top">Amazing picture!  I see a ribbon on this one.</td>', 'Amazing picture!  I see a ribbon on this one.', '2007-04-23 01:46:31.000000', NULL, 1),
(3572197, 501477, 16402, '<td valign="top">I''m not one of the DNMC nazi''s that''s gonna hold this against you, but honestly, because of your focus the subject of this seems to be the strawberry rather than the wisk.</td>', 'I''m not one of the DNMC nazi''s that''s gonna hold this against you, but honestly, because of your focus the subject of this seems to be the strawberry rather than the wisk.', '2007-04-23 01:49:29.000000', NULL, 1),
(3572201, 500779, 16402, '<td valign="top">Love it, very graphic and creative. Good effort. 8</td>', 'Love it, very graphic and creative. Good effort. 8', '2007-04-23 01:51:01.000000', NULL, 1),
(3572205, 500976, 16402, '<td valign="top">Very interesting abstract.</td>', 'Very interesting abstract.', '2007-04-23 01:51:47.000000', NULL, 1),
