(3572413, 501140, 49109, '<td valign="top">priceless expression! good lighting. excellent post-processing. crop is a bit tight.</td>', 'priceless expression! good lighting. excellent post-processing. crop is a bit tight.', '2007-04-23 04:37:17.000000', NULL, 1),
