(3573185, 500112, 61651, '<td valign="top">This is very creative, I do like it - it does seem a bit hemmed in on the sides though, and might benefit from less cropping.</td>', 'This is very creative, I do like it - it does seem a bit hemmed in on the sides though, and might benefit from less cropping.', '2007-04-23 11:31:58.000000', NULL, 1),
(3573199, 499701, 42196, '<td valign="top">Haha, funny title.  Think she''d be happy bout that?<br/>Also funny that you can only see ''HO'' on her shirt.</td>', 'Haha, funny title.  Think she''d be happy bout that?Also funny that you can only see ''HO'' on her shirt.', '2007-04-23 11:38:33.000000', NULL, 1),
