(3573270, 500457, 66353, '<td valign="top">Very nice perspective - and your tint works very good with this image.</td>', 'Very nice perspective - and your tint works very good with this image.', '2007-04-23 12:08:06.000000', NULL, 1),
(3573282, 501494, 56880, '<td valign="top">I like the idea, but the focus is too soft.  I think if you tightened the crop a bit on the top and bottom, it''d make the line of forks appear endless; the gap in the upper right is a bit distracting.</td>', 'I like the idea, but the focus is too soft.  I think if you tightened the crop a bit on the top and bottom, it''d make the line of forks appear endless; the gap in the upper right is a bit distracting.', '2007-04-23 12:13:05.000000', NULL, 1),
(3573288, 500905, 64929, '<td valign="top">The vibrant blue hue really makes this shot go from ordinary to XTRA-ordinary! *7*</td>', 'The vibrant blue hue really makes this shot go from ordinary to XTRA-ordinary! *7*', '2007-04-23 12:14:51.000000', NULL, 1),
(3573298, 501048, 75898, '<td valign="top">The plate is distracting IMHO.  The blue edge would be really nice without the sunflowers, they compete with the lemon.</td>', 'The plate is distracting IMHO.  The blue edge would be really nice without the sunflowers, they compete with the lemon.', '2007-04-23 12:17:21.000000', NULL, 1),
