(3573303, 501007, 64929, '<td valign="top">I love the way the lettuce works at the bottom of the shot...great stuff! *7*</td>', 'I love the way the lettuce works at the bottom of the shot...great stuff! *7*', '2007-04-23 12:18:26.000000', NULL, 1),
(3573309, 499148, 75898, '<td valign="top">I think a different angle would work better with this picture.  Also, the lighting is a bit harsh (I''ve found that the built-in flashes hardly ever work best...try using a totally separate light source set at a different angle).</td>', 'I think a different angle would work better with this picture.  Also, the lighting is a bit harsh (I''ve found that the built-in flashes hardly ever work best...try using a totally separate light source set at a different angle).', '2007-04-23 12:21:24.000000', NULL, 1),
(3573321, 501438, 75898, '<td valign="top">I like the processing on this...curious to see how it was done.</td>', 'I like the processing on this...curious to see how it was done.', '2007-04-23 12:24:52.000000', NULL, 1),
