(3577043, 501292, 73235, '<td valign="top">nice capture of an ordinary object. the harsh flash takes a little away from the overall tone scheme. good DOF</td>', 'nice capture of an ordinary object. the harsh flash takes a little away from the overall tone scheme. good DOF', '2007-04-24 13:44:17.000000', NULL, 1),
