INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3578837, 500576, 37320, '<td valign="top">The cheese man is a charming subject, but I think the audience wants to see him involved in a complex plot.  Maybe take a picture where he is hanging off the side of a helicopter trying to rescue the salt shaker or something.</td>', 'The cheese man is a charming subject, but I think the audience wants to see him involved in a complex plot.  Maybe take a picture where he is hanging off the side of a helicopter trying to rescue the salt shaker or something.', '2007-04-24 23:17:48.000000', NULL, 1),
(3578840, 500546, 37320, '<td valign="top">If you put some tobasco in this picture I think Id give you an even higher score.  The way it looks now I feel a little queasy thinking that someone might eat those as is.</td>', 'If you put some tobasco in this picture I think Id give you an even higher score.  The way it looks now I feel a little queasy thinking that someone might eat those as is.', '2007-04-24 23:18:53.000000', NULL, 1),
(3578841, 499338, 37320, '<td valign="top">Cool effect!</td>', 'Cool effect!', '2007-04-24 23:19:07.000000', NULL, 1),
(3578843, 500550, 71608, '<td valign="top">I really like this, great perspective and cool style numbers, but maybe a bit lighter?</td>', 'I really like this, great perspective and cool style numbers, but maybe a bit lighter?', '2007-04-24 23:19:18.000000', NULL, 1),
(3578850, 501463, 37320, '<td valign="top">This is what I''ve wanted to see this whole challenge!  All of the other utensils dont seem to have night lives....not this one!  While the knives and forks sleep quietly in the drawer after their moment of fame in the photo shoot, this strainer goes out and boogies.  I know a cute cheese grater I can hook it up with if it''s interested.</td>', 'This is what I''ve wanted to see this whole challenge!  All of the other utensils dont seem to have night lives....not this one!  While the knives and forks sleep quietly in the drawer after their moment of fame in the photo shoot, this strainer goes out and boogies.  I know a cute cheese grater I can hook it up with if it''s interested.', '2007-04-24 23:21:09.000000', NULL, 1),
(3578852, 501333, 37320, '<td valign="top">Aww poor fork.  I still love you.</td>', 'Aww poor fork.  I still love you.', '2007-04-24 23:21:38.000000', NULL, 1),
(3578857, 500567, 37320, '<td valign="top">Nice coloration, you get the feel thise grater is being used at some social event as opposed to making quesadillas for some lonely person at midnight.</td>', 'Nice coloration, you get the feel thise grater is being used at some social event as opposed to making quesadillas for some lonely person at midnight.', '2007-04-24 23:22:47.000000', NULL, 1),
