(3578869, 501497, 69102, '<td valign="top">Ouch!! ;) Very creative.</td>', 'Ouch!! ;) Very creative.', '2007-04-24 23:24:33.000000', NULL, 1),
(3578877, 501467, 37320, '<td valign="top">Your stove is really clean, while im sure that makes it nice to cook on I really was searching for some kind of hidden subject.  Its almost too perfect...who am I kidding...Im just jealous..nice picture...and stove.</td>', 'Your stove is really clean, while im sure that makes it nice to cook on I really was searching for some kind of hidden subject.  Its almost too perfect...who am I kidding...Im just jealous..nice picture...and stove.', '2007-04-24 23:25:51.000000', NULL, 1),
