(3586608, 499338, 66952, '<td valign="top">I can''t decide if I like the post processing, or if it''s over the top. It''s definitely different than the other 100 pictures of whisks and colanders I''ve looked at today, so I think I like it....reminds me of the place I worked when I was in college, many eons ago.</td>', 'I can''t decide if I like the post processing, or if it''s over the top. It''s definitely different than the other 100 pictures of whisks and colanders I''ve looked at today, so I think I like it....reminds me of the place I worked when I was in college, many eons ago.', '2007-04-26 21:44:46.000000', NULL, 1),
(3586802, 501477, 55906, '<td valign="top">Good composition, but strawberry is not crisp</td>', 'Good composition, but strawberry is not crisp', '2007-04-26 22:54:19.000000', NULL, 1),
(3586810, 500976, 55906, '<td valign="top">Good composition, but the reflection of the first spoon is distracting.</td>', 'Good composition, but the reflection of the first spoon is distracting.', '2007-04-26 22:56:26.000000', NULL, 1),
(3586812, 501494, 55906, '<td valign="top">Nice use of depth of field. Very clean composition</td>', 'Nice use of depth of field. Very clean composition', '2007-04-26 22:56:52.000000', NULL, 1),
(3586818, 501480, 55906, '<td valign="top">The minimalistic approach works well. The table cloth should have been a bit more soft. The patterns distract the main subject focus.</td>', 'The minimalistic approach works well. The table cloth should have been a bit more soft. The patterns distract the main subject focus.', '2007-04-26 22:58:12.000000', NULL, 1),
(3586823, 498515, 55906, '<td valign="top">There is no clear-cut subject. Would have been better if one or two elements are picked instead of all.</td>', 'There is no clear-cut subject. Would have been better if one or two elements are picked instead of all.', '2007-04-26 22:58:52.000000', NULL, 1),
(3586826, 500722, 55906, '<td valign="top">Concept is great. Nice shot of the exploding juice! Should''ve cut the bottom portion of the blender. Does not blend well with the top.</td>', 'Concept is great. Nice shot of the exploding juice! Should''ve cut the bottom portion of the blender. Does not blend well with the top.', '2007-04-26 22:59:46.000000', NULL, 1),
(3586828, 500432, 55906, '<td valign="top">Nice concept</td>', 'Nice concept', '2007-04-26 23:00:03.000000', NULL, 1),
