(3586921, 499087, 7485, '<td valign="top">Good concept and nice lighting, but I''d have gone for perfect symmetry, with same size spoons and same amount of space on either side.</td>', 'Good concept and nice lighting, but I''d have gone for perfect symmetry, with same size spoons and same amount of space on either side.', '2007-04-26 23:26:49.000000', NULL, 1),
(3587002, 500462, 52130, '<td valign="top">cute...could have been executed better, but it''s cute.</td>', 'cute...could have been executed better, but it''s cute.', '2007-04-26 23:56:27.000000', NULL, 1),
(3587010, 500745, 52130, '<td valign="top">As a composition connoisseur myself, I really love this. Very simple, but strong. good luck.</td>', 'As a composition connoisseur myself, I really love this. Very simple, but strong. good luck.', '2007-04-26 23:58:10.000000', NULL, 1),
